// v2.7: positions are data, ready for future placement abilities (none enabled).
const TEAM_MODES27={solo:{name:'1vs1',size:1,cap:5,positions:['先鋒']},duo:{name:'2vs2',size:2,cap:8,positions:['先鋒','大将']},trio:{name:'3vs3',size:3,cap:12,positions:['先鋒','次鋒','大将']}};
function extendTeamSave27(out,source={}){const old=source.teamBattle27||{},forms={};for(const [key,m] of Object.entries(TEAM_MODES27)){const seen=new Set();forms[key]=Array.from({length:m.size},(_,i)=>{const id=old.formations?.[key]?.[i];if(!out.cards[id]||!GAME_DATA.cards.some(c=>c.id===id)||seen.has(id))return null;seen.add(id);return id;});}out.teamBattle27={...old,schema:1,mode:TEAM_MODES27[old.mode]?old.mode:'solo',formations:forms};return out;}
function teamCost27(ids){return ids.reduce((n,id)=>n+(GAME_DATA.cards.find(c=>c.id===id)?.rarity||0),0);}
function validateTeam27(ids,mode,owned=null){const m=TEAM_MODES27[mode];if(!m)return {ok:false,message:'モードを選んでください'};const cards=ids.map(id=>GAME_DATA.cards.find(c=>c.id===id));const cost=teamCost27(ids);let message='編成完了！ この順番で出撃できます。';if(ids.length!==m.size||cards.some(c=>!c))message=`${m.size}枚のカードを選んでください`;else if(new Set(ids).size!==m.size)message='同じカードは1チームに1枚までです';else if(owned&&ids.some(id=>!owned[id]))message='所持カードから選んでください';else if(cost>m.cap)message='★上限を超えています';return {ok:message.startsWith('編成完了'),message,cost,cap:m.cap};}
function cpuTeam27(mode,rng=Math.random){const m=TEAM_MODES27[mode],picked=[];let budget=m.cap;while(picked.length<m.size){const available=GAME_DATA.cards.filter(c=>!picked.includes(c.id)),remaining=m.size-picked.length-1;const eligible=available.filter(c=>{const minimum=available.filter(x=>x.id!==c.id).map(x=>x.rarity).sort((a,b)=>a-b).slice(0,remaining);return minimum.length===remaining&&c.rarity+minimum.reduce((a,b)=>a+b,0)<=budget;});if(!eligible.length)throw Error('CPU編成を作れません');const c=eligible[Math.min(eligible.length-1,Math.floor(rng()*eligible.length))];picked.push(c.id);budget-=c.rarity;}return picked;}
function member27(id,index,mode,cpu=false){const c=GAME_DATA.cards.find(c=>c.id===id),card=battleCard26(c,cpu?0:level26(c));return {id,card,index,position:TEAM_MODES27[mode].positions[index],placementAbility:null,hp:battleProfile24(card).hp,rallyUsed:false,kills:0,defeated:false};}
function createMatch27(playerIds,cpuIds,mode){if(!validateTeam27(playerIds,mode).ok||!validateTeam27(cpuIds,mode).ok)throw Error('Invalid team');const d={mode,playerTeam:playerIds.map((id,i)=>member27(id,i,mode)),cpuTeam:cpuIds.map((id,i)=>member27(id,i,mode,true)),pIndex:0,cIndex:0,round:1,clashTurn:1,phase:'intro',busy:true,ended:false,logs:[],last:null};syncActive27(d);return d;}
function syncActive27(d){const p=d.playerTeam[d.pIndex],c=d.cpuTeam[d.cIndex];d.player=p.card;d.cpu=c.card;d.pHP=p.hp;d.cHP=c.hp;d.pRally=p.rallyUsed;d.cRally=c.rallyUsed;}
function applyTurn27(d,da,db,stance,cpuStance){const p=d.playerTeam[d.pIndex],c=d.cpuTeam[d.cIndex],r=resolveClash24(p.card,c.card,da,db,stance,cpuStance,d.clashTurn);if(stance==='rally')p.rallyUsed=true;if(cpuStance==='rally')c.rallyUsed=true;p.hp=round26(Math.max(0,Math.min(battleProfile24(p.card).hp,p.hp+r.player.heal)-r.toPlayer));c.hp=round26(Math.max(0,Math.min(battleProfile24(c.card).hp,c.hp+r.cpu.heal)-r.toCPU));const deadP=p.hp<=0,deadC=c.hp<=0;if(deadP){p.defeated=true;c.kills++;}if(deadC){c.defeated=true;p.kills++;}d.last=r;syncActive27(d);const exhaustedP=deadP&&d.pIndex===d.playerTeam.length-1,exhaustedC=deadC&&d.cIndex===d.cpuTeam.length-1;let outcome=null;if(exhaustedP||exhaustedC)outcome=exhaustedP&&exhaustedC?'draw':exhaustedC?'win':'loss';return {r,deadP,deadC,outcome};}
function advanceMatch27(d){const sides=[];if(d.playerTeam[d.pIndex].defeated&&d.pIndex+1<d.playerTeam.length){d.pIndex++;sides.push('player');}if(d.cpuTeam[d.cIndex].defeated&&d.cIndex+1<d.cpuTeam.length){d.cIndex++;sides.push('cpu');}syncActive27(d);d.round++;d.clashTurn=1;d.phase='fight';d.busy=false;d.last=null;return sides;}
